#include <stdio.h>
#include <string.h>
#include <ctype.h>

static int is_leap_year(int year)
{
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

int main(int argc, char **argv)
{
    const char *msg_invalid = "INVALID";
    const char *msg_valid   = "VALID";

    if (argc < 2) {
        puts(msg_invalid);
        return 0;
    }

    const char *s = argv[1];

    if (strlen(s) != 10) {
        puts(msg_invalid);
        return 0;
    }

    for (int i = 0; i < 10; ++i) {
        if (!isdigit((unsigned char)s[i])) {
            puts(msg_invalid);
            return 0;
        }
    }

    int year  = (s[0] - '0') * 1000 + (s[1] - '0') * 100 + (s[2] - '0') * 10 + (s[3] - '0');
    int month = (s[5] - '0') * 10 + (s[6] - '0');
    int day   = (s[8] - '0') * 10 + (s[9] - '0');

    if (month < 1 || month > 12) {
        puts(msg_invalid);
        return 0;
    }

    if (day < 1) {
        puts(msg_invalid);
        return 0;
    }

    static const int days_in_month[13] = {0,31,28,31,30,31,30,31,31,30,31,30,31};
    int max_day = days_in_month[month];
    if (month == 2 && is_leap_year(year))
        max_day = 29;

    if (day > max_day) {
        puts(msg_invalid);
        return 0;
    }

    puts(msg_valid);
    return 0;
}
